Platform-specific conditional logic (`!isWeb`) is being used to control which accessibility props are applied, mixing platform concerns within the component.

**Suggested fix:** Use platform-specific file extensions or extract to a helper that returns the appropriate props per platform:

```tsx
// utils/getAccessibilityProps.ts or .native.ts/.web.ts
export function getErrorAccessibilityProps(shouldAnnounce: boolean) {
    if (!shouldAnnounce) return {};

    return {
        role: CONST.ROLE.ALERT,
        accessibilityRole: CONST.ROLE.ALERT, // Native only
        accessibilityLiveRegion: 'assertive' as const, // Native only
    };
}

// FormHelpMessage.tsx
<Text
    style={[isError ? styles.formError : styles.formHelp, styles.mb0]}
    {...getErrorAccessibilityProps(shouldAnnounceError)}
>
    {message}
</Text>
```

